entries[82346] = { ["name"] = "Feuerkrug", ["text"] = "Questgegenstand\nBenutzen: Auf einen Sra'thik-Kriegswagen werfen. Nehmt Euch vor rachsüchtigen Mantis in acht!" }
entries[82353] = { ["name"] = "Sra'thik-Waffe", ["text"] = "Questgegenstand\n\"Von den einfallenden Mantis der Sra'thik erbeutet.\"" }
entries[82381] = { ["name"] = "Yakmilchflasche", ["text"] = "Questgegenstand\nBenutzen: Flößt dies einem verwundeten Niuzaobewacher ein, um ihn wieder auf die Beine zu bringen." }
entries[82387] = { ["name"] = "Volle Mushanblase", ["text"] = "Questgegenstand\n\"Ihr haltet es für eine GROSSARTIGE Idee, sie in Eure Tasche zu packen.\"" }
entries[82388] = { ["name"] = "Fragment eines Ranzbisspanzers", ["text"] = "Questgegenstand\n\"Hart, schuppig und von einheitlicher Größe - ideal für Kettenrüstungen!\"" }
entries[82389] = { ["name"] = "Mao-Weide", ["text"] = "Questgegenstand\n\"Die blühenden Zweige sind leicht und sowohl weich als auch stachlich.\"" }
entries[82392] = { ["name"] = "Gummitang", ["text"] = "Benutzen: Löst einen zufälligen Effekt aus! Es besteht eine Chance, dass Gesundheit oder eine nützliche Ressource wiederhergestellt wird. Funktioniert nur am Perlsee im Jadewald.\n\"Die grünen Blätter sind saftig und erfrischend.\"" }
entries[82393] = { ["name"] = "Abpausbild von Schriften der Shen-Dynastie", ["text"] = "Questgegenstand\n\"Der Text auf dieser Tafel war so abgenutzt, dass es schwer fällt, die Symbole auf diesem Bild zu entziffern.\"" }
entries[82394] = { ["name"] = "Abpausbild von Schriften der Qiang-Dynastie", ["text"] = "Questgegenstand\n\"Tief in die Tafel eingekerbte Symbole haben dieses Bild leicht zu lesen gemacht.\"" }
entries[82395] = { ["name"] = "Abpausbild von Schriften der Wai-Dynastie", ["text"] = "Questgegenstand\n\"Dieses Bild zeigt nur einen kleinen Teil der Schriftzeichen auf der zerbrochenen Tafel.\"" }
entries[82396] = { ["name"] = "Rezept: Formattest", ["text"] = "Benutzen: 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650 1650LANGLANGLANLAN\nEine Nahkampfwaffe dauerhaft verzaubern, sodass Eure Heilungen oder Schaden verursachenden Zauber manchmal Eure Intelligenz um 1650 erhöhen. Wenn Ihr über weniger als 25% Mana verfügt, während dieser Effekt ausgelöst wird, wird Eure Willenskraft ebenfalls um 0 erhöht." }
