entries[82787] = { ["name"] = "Zitronengetränkte Bandagen", ["text"] = "Questgegenstand\nBenutzen: Heilt eine verletzte Schwarzwache von Gao-Ran 6 Sek. lang um 60% ihrer Gesundheit." }
