entries[83094] = { ["name"] = "Footes Dreifachgebrannter", ["text"] = "Benötigt Stufe 90\nBenutzen: Ein starkes alkoholisches Getränk.\n\"Überraschend stark.\"\nVerkaufspreis:" }
entries[83095] = { ["name"] = "Lagrave Bock", ["text"] = "Benötigt Stufe 85\nBenutzen: Ein ziemlich schwaches alkoholisches Getränk.\n\"Der dunkle, vollmundige Geschmack erinnert leicht an getrocknete Früchte und Schokolade.\"\nVerkaufspreis:" }
entries[83096] = { ["name"] = "Glyphe 'Anstacheln'", ["text"] = "Erhebliche Glyphe\nKlassen: Krieger\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nDer Einsatz von 'Demoralisierender Ruf' hebt die Wutkosten Eurer nächsten drei Einsätze von 'Heldenhafter Stoß' oder 'Spalten' auf.\nVerkaufspreis:" }
entries[83097] = { ["name"] = "Schildkrötendörrfleisch", ["text"] = "Benötigt Stufe 85\nBenutzen: Stellt im Verlauf von 20 Sek. 199999 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Zäh und fleischig.\"\nVerkaufspreis:" }
entries[83107] = { ["name"] = "Glyphe 'Massenexorzismus'", ["text"] = "Erhebliche Glyphe\nKlassen: Paladin\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Reichweite von 'Exorzismus' auf Nahkampfreichweite, fügt jedoch allen Gegnern im Umkreis von 8 Metern um das Hauptziel 25% Schaden zu.\nVerkaufspreis:" }
entries[83120] = { ["name"] = "Bernmedaillon", ["text"] = "\"Ein wunderschönes, aber inaktives Stück Bern.\"\nVerkaufspreis:" }
entries[83124] = { ["name"] = "Becher voll Dschungelbräu", ["text"] = "Questgegenstand\n\"Dieser dampfende Krug hat vielfältige Gerüche und Geschmäcker.\"" }
entries[83127] = { ["name"] = "Strandbombe", ["text"] = "Unga Ingu\nWird beim Aufheben gebunden\nBenutzen: Platziert eine Strandbombe auf dem Boden, die dem ersten sich nähernden Gegner Schaden zufügt. Die Bombe besteht 5 Min. lang. (5 Sek. Abklingzeit)\n\"Dieser Sprengsatz ist dazu eingerichtet, alle Ho-zen, die sich ihm nähern, zu verletzen.\"" }
entries[83128] = { ["name"] = "Bräuverteidigerkugel", ["text"] = "Unga Ingu\nEinzigartig\nDauer: 10 min (Realzeit)\nBenutzen: Verwandelt Euch 10 Min. lang in ein Pandajunges." }
entries[83129] = { ["name"] = "Ei eines Wolkenreiters", ["text"] = "Questgegenstand\n\"Ziemlich schwer.\"" }
entries[83130] = { ["name"] = "Tafel der Shan'ze", ["text"] = "Questgegenstand\n\"Ein uralter Text ist in das steinerne Gesicht gehauen.\"" }
entries[83131] = { ["name"] = "Kanonenleuchtfeuer", ["text"] = "Unga Ingu\nWird beim Aufheben gebunden\nBenutzen: Wirft ein Signalleuchtfeuer für Don-Don den Bierverteidiger ab.\n\"Auf der Seite des Leuchtfeuers steht \"Schönen Tag noch, Nappel!\".\"" }
entries[83134] = { ["name"] = "Bronzeklauen", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Nutzt Eure Stahlklauen, um Euch sicher an einer vorbeifliegenden Sturmklaue der Shan'ze festzuhaken." }
entries[83135] = { ["name"] = "Bernklinge", ["text"] = "Questgegenstand\n\"Die Waffen der Mantis bestehen aus Bern, der zu langen, gebogenen Klingen geschmiedet wurde. Diese Waffen sind ideal zum Schneiden, leichtgewichtig und genauso robust wie Waffen aus Metall.\"" }
entries[83136] = { ["name"] = "Köcher voll Feuerpfeile der Shado-Pan", ["text"] = "Questgegenstand\n\"In Pech getaucht und zur Nutzung bereit.\"" }
entries[83137] = { ["name"] = "Medizinbeutel der Ho-zen", ["text"] = "Unga Ingu\nEinzigartig\nBenutzen: Belebt ein verbündetes Ziel wieder. Funktioniert nur außerhalb des Kampfes.\n\"Eine Mischung aus Kräutern und Salben wird auf den Finger gerieben und dann ins Ohr gesteckt.\"" }
entries[83138] = { ["name"] = "Herz aus Onyx", ["text"] = "Questgegenstand\n\"Scharf wie Glas und hart wie Stein.\"" }
